if (element.nextElementSibling && element.nextElementSibling.classList.contains('recommended-self-help')) {
    return;
}

var block = document.createElement('section');
block.className = 'recommended-self-help';
block.setAttribute('aria-label', 'Recommended Self-Help');

var title = document.createElement('h2');
title.className = 'recommended-self-help-title';
title.textContent = 'Recommended Self-Help';
block.appendChild(title);

var container = document.createElement('div');
container.className = 'recommended-self-help-links';

// Collect related articles links
var relatedSection = element.closest('.article') && element.closest('.article').querySelector('.related-articles ul');
if (relatedSection) {
    var relatedLi = relatedSection.querySelectorAll('li a');
    for (var i = 0; i < relatedLi.length; i++) {
        var link = relatedLi[i];
        if (link && link.href && link.textContent.trim()) {
            var item = document.createElement('div');
            item.className = 'recommended-self-help-item';
            var a = document.createElement('a');
            a.href = link.href;
            a.textContent = link.textContent.trim();
            a.setAttribute('rel', 'nofollow');
            item.appendChild(a);
            container.appendChild(item);
        }
    }
}

// Collect sidebar links
var sidebarBody = element.closest('.article-container') && element.closest('.article-container').querySelector('.collapsible-sidebar-body ul');
if (sidebarBody) {
    var sidebarLi = sidebarBody.querySelectorAll('li a.sidenav-item');
    for (var j = 0; j < sidebarLi.length; j++) {
        var sLink = sidebarLi[j];
        if (sLink && sLink.href && sLink.textContent.trim()) {
            // Avoid duplicates
            var href = sLink.href;
            var alreadyAdded = false;
            var existingLinks = container.querySelectorAll('a');
            for (var k = 0; k < existingLinks.length; k++) {
                if (existingLinks[k].href === href) {
                    alreadyAdded = true;
                    break;
                }
            }
            if (!alreadyAdded) {
                var item2 = document.createElement('div');
                item2.className = 'recommended-self-help-item';
                var a2 = document.createElement('a');
                a2.href = href;
                a2.textContent = sLink.textContent.trim();
                item2.appendChild(a2);
                container.appendChild(item2);
            }
        }
    }
}

block.appendChild(container);

// Add styles
var styleId = 'recommended-self-help-styles';
if (!document.getElementById(styleId)) {
    var style = document.createElement('style');
    style.id = styleId;
    style.textContent = 
        '.recommended-self-help {' +
            'background: #f0f4ff;' +
            'border: 2px solid #4a76a8;' +
            'border-radius: 8px;' +
            'padding: 16px 20px;' +
            'margin-top: 16px;' +
        '}' +
        '.recommended-self-help-title {' +
            'font-size: 18px;' +
            'font-weight: 700;' +
            'color: #1a1a2e;' +
            'margin: 0 0 12px 0;' +
        '}' +
        '.recommended-self-help-links {' +
            'display: grid;' +
            'grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));' +
            'gap: 8px;' +
        '}' +
        '.recommended-self-help-item a {' +
            'display: block;' +
            'padding: 8px 12px;' +
            'color: #2c5aa0;' +
            'text-decoration: none;' +
            'border-radius: 4px;' +
            'font-size: 14px;' +
            'transition: background 0.15s ease;' +
        '}' +
        '.recommended-self-help-item a:hover {' +
            'background: #dce6f5;' +
            'text-decoration: underline;' +
        '}';
    document.head.appendChild(style);
}

element.parentNode.insertBefore(block, element.nextSibling);

